import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BvlN9b-o.js";const b=JSON.parse('{"title":"Core 与参考业务的边界","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/boundaries.md","filePath":"architecture/boundaries.md"}'),s={name:"architecture/boundaries.md"};function i(n,e,c,l,d,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="core-与参考业务的边界" tabindex="-1">Core 与参考业务的边界 <a class="header-anchor" href="#core-与参考业务的边界" aria-label="Permalink to &quot;Core 与参考业务的边界&quot;">​</a></h1><p>Core 提供身份、会话、成员、审计、幂等、文件、任务、通知和通用 HTTP 能力。Reference Domain 通过应用入口接入自己的业务；Core 不反向依赖它。</p><ul><li><strong>platform</strong> 拥有配置、连接池、迁移运行与日志初始化，不依赖应用或知识库类型。</li><li><strong>app</strong> 的各个模块拥有自己的用例和表；纯 <code>domain.rs</code> 不依赖 HTTP 或数据库。</li><li><strong>API 入口</strong> 在 <code>apps/api/src/lib.rs</code> 组装 Router/OpenAPI，通用构建器接收额外路由与合同。</li><li><strong>contracts / sdk</strong> 来自 OpenAPI 生成；SDK 的类型使用 contracts。</li><li><strong>core</strong> 放平台无关的客户端 helper。</li><li><strong>ui / views</strong> 分别提供通用 React DOM 组件与可共享页面。</li><li><strong>Web 入口</strong> 拥有浏览器和 Router 接线，shared View 通过回调导航。</li></ul><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/c8786bd3c5848a35fed1e00c93b0718f1224546d/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">示例所有权清单</a>记录业务目录、迁移、测试、教程和明确的组装区块。新增功能时同步登记；后续移除工具按登记内容操作，Core 的能力不会随参考业务一起删除。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span></code></pre></div><p>当前检查验证包导入方向、Core 对参考类型的直接引用、纯 Domain 的基础设施导入、模块声明的 SQL 表归属，以及组装清单。每个 Rust 模块的 <code>module.json</code> 是表归属入口；跨模块通过公开接口协作，例如让 Audit 在调用者事务中追加记录。</p><p>SQL 检查基于源码中的字符串和已登记表名，不能证明动态 SQL、引号标识符或符号别名的全部行为；这些仍需 review。Rust 可见性与真实 HTTP/数据库测试共同补充验证。实际删例验收由移除工具对应任务执行。</p><p>引入自己的业务时，使用公开身份、文件和任务能力；不要让 Core 通过私有表或反向 import 依赖示例。进一步决策见<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/c8786bd3c5848a35fed1e00c93b0718f1224546d/docs/adr/0002-executable-removable-reference.md" target="_blank" rel="noreferrer">可移除教程 ADR</a>。</p><p>Notifications 拥有任务通知意图和收件箱；业务用公开接口在请求事务中登记意图，Jobs 在终态事务中发布通知。导航目标由应用壳解析，Core View 通过回调打开；目标 API 始终重新授权。未知目标不影响读取与标记已读。</p><hr><p>源码版本：<code>c8786bd3c584</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/c8786bd3c5848a35fed1e00c93b0718f1224546d/docs/architecture/module-boundaries.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>',11)])])}const h=a(s,[["render",i]]);export{b as __pageData,h as default};
